'use strict';
(()=>{
const canWrite=()=>!window.markCloud?.active||window.markCloud.writable;
const monthly=()=>window.ROADMAP.checkpoints.filter(c=>!c.id.startsWith('week')).map(c=>window.planEngine.effective(c,state));
const bySubject=k=>window.TOPICS.filter(t=>t.subject===k);
function dates(cp,k){if(window.subjectFlow)cp=window.subjectFlow.effective(cp,state,k);const count=cp.examCount||1,span=Math.round((parse(cp.end)-parse(cp.start))/86400000)+1,offset={math:0,ru:2,physics:4}[k];return Array.from({length:count},(_,i)=>shift(cp.start,Math.max(0,Math.min(span-1,Math.floor((i+1)*span/(count+1))-2+offset))))}
function checkpoint(cp){return `<section class="mock-step"><h3>${cp.id==='2026-09'?'Первый пробник — узнать старт':'Пробники и разбор ошибок'}</h3><p class="muted">Полный вариант на время. ${cp.id==='2026-09'?'Неизученные задания можно пропустить: сейчас важно увидеть пробелы.':'После проверки запиши балл и отметь задания с ошибками или пропусками.'}</p><div class="mock-dates">${Object.keys(names).map(k=>{const actual=window.subjectFlow?window.subjectFlow.effective(cp,state,k):cp,runs=state.exams.filter(e=>e.subject===k&&e.date>=actual.start&&e.date<=actual.end&&e.date<=today);return `<div><strong class="${k}">${names[k]}</strong><span>${dates(cp,k).map(fmt).join(' · ')} · ${k==='ru'?'3 ч 30 мин':'3 ч 55 мин'}</span><small>Записано: ${runs.length} / ${cp.examCount||1}</small><button data-mock="${cp.id}" data-mock-subject="${k}" data-roadmap-write>Записать результат</button></div>`}).join('')}</div><p><strong>До ${fmt(cp.end)}:</strong> разобрать ошибки → отметить трудные номера → обновить траекторию. Через неделю проверить их на новых заданиях.</p><p class="muted">Это предлагаемые даты: фактическую дату можно изменить. Пробники заменяют обычную подготовку в эти дни; перенеси занятия в недельном плане.</p></section>${milestone(cp)}`}
function milestone(cp){if(!['2026-12','2027-03','2027-05'].includes(cp.id))return '';const end=cp.id==='2026-12'?'К концу декабря':cp.id==='2027-03'?'К концу марта':'Перед ЕГЭ',skills={ru:'Расставлять ударения, выбирать верные слова и формы, применять изученные правила написания слов.',math:'Вычислять, решать основные уравнения, задачи на геометрию, вероятность и по текстовому условию.',physics:'Выбирать законы для движения, сил, энергии и тепловых процессов; работать с единицами и объяснять решение.'};return `<aside class="ability-step"><h3>${end}: что я должен уметь</h3>${Object.keys(names).map(k=>{const list=bySubject(k).filter(t=>t.period<=cp.id);return `<p><strong>${names[k]}:</strong> ${cp.id==='2026-12'?skills[k]:cp.id==='2027-03'?'Понимать способ решения всех типов заданий, самостоятельно решать пройденные варианты и знать оставшиеся слабые места.':'Решать полный вариант в отведённое время, проверять ответы и удерживать личный целевой балл на трёх пробниках подряд.'}<br><small>Ориентир по заданиям: ${list.map(t=>'№'+t.code).join(', ')}.</small></p>`}).join('')}<p class="muted">Проверка — новые задания без подсказок, затем повторение через неделю. Это цель подготовки, а не обещание результата; незакрытые номера остаются в работе.</p></aside>`}
const dialog=document.createElement('dialog');dialog.id='mockDialog';dialog.innerHTML=`<form id="mockForm"><div class="sectionhead"><h2>Результат пробника</h2><button type="button" id="mockClose" aria-label="Закрыть">×</button></div><label>Предмет<select name="subject">${Object.entries(names).map(([k,n])=>`<option value="${k}">${n}</option>`).join('')}</select></label><label>Фактическая дата<input name="date" type="date" max="${today}" required></label><label>Балл ЕГЭ, 0–100<input name="score" type="number" min="0" max="100" step="1" required></label><p>Отметь номера, которые не получились, решены не полностью или пропущены.</p><div id="failedNumbers" class="failed-numbers"></div><label class="inline"><input name="updatePlan" type="checkbox" checked> Обновить траекторию по этим ошибкам</label><p class="muted">Трудные задания вернутся в работу. Задания без отметки не считаются автоматически освоенными. Балл сохранится, даже если пересчитать сроки не удастся.</p><div class="formbuttons"><button type="button" id="mockDelete" class="danger">Удалить</button><button type="submit" class="primary">Сохранить результат</button></div></form>`;document.body.append(dialog);
let editingId=null;
function numbers(failed=[]){const k=$('#mockForm').elements.subject.value;$('#failedNumbers').innerHTML=bySubject(k).map(t=>`<label title="${escape(t.title)}"><input type="checkbox" name="failed" value="${t.code}" ${failed.includes(Number(t.code))?'checked':''}> №${t.code}</label>`).join('')}
function open(id,subject,cpid){if(!canWrite())return;editingId=id||null;const item=state.exams.find(e=>e.id===id),f=$('#mockForm');f.reset();f.elements.subject.value=item?.subject||subject||'math';f.elements.date.value=item?.date||today;f.elements.score.value=item?.score??'';f.elements.updatePlan.checked=!item;$('#mockDelete').hidden=!item;numbers(item?.failed||[]);dialog.showModal()}
$('#mockClose').onclick=()=>dialog.close();$('#mockForm').elements.subject.onchange=()=>numbers();$('#mockDelete').onclick=()=>{if(!canWrite()||!confirm('Удалить результат пробника? Отметки заданий останутся.'))return;state.exams=state.exams.filter(e=>e.id!==editingId);save();dialog.close();render()};
function apply(source,exam){const out=JSON.parse(JSON.stringify(source));out.strategy={...out.strategy,topics:{...out.strategy?.topics}};for(const n of exam.failed||[])out.strategy.topics[`${exam.subject}-task-${n}`]={status:'struggling',at:today};return window.subjectFlow?window.subjectFlow.assign(out,exam.subject,today):window.topicEngine.rebalance(out,today).state}
$('#mockForm').onsubmit=e=>{e.preventDefault();if(!canWrite())return;const f=e.target.elements,item={id:editingId||uid(),subject:f.subject.value,date:f.date.value,score:Number(f.score.value),failed:[...document.querySelectorAll('#failedNumbers input:checked')].map(e=>Number(e.value))};if(!window.validateExamDetails(item)||item.date>today)return;const old=state.exams.find(e=>e.id===editingId);if(old)Object.assign(old,item);else state.exams.push(item);if(f.updatePlan.checked){state=apply(state,item);if(item.failed.length){const cp=monthly().find(c=>(window.subjectFlow?window.subjectFlow.effective(c,state,item.subject):c).end>=today)||monthly().at(-1);window.subjectFlow?window.subjectFlow.update(item.subject,cp.id,'struggling',true):window.replanFromTopic(cp.id)}else save()}else save();dialog.close();render();toast('Пробник сохранён'+(f.updatePlan.checked?' · ошибки учтены в траектории':''))};
document.addEventListener('click',e=>{const b=e.target.closest('[data-mock]');if(b)open(null,b.dataset.mockSubject,b.dataset.mock)});
window.validateExamDetails=e=>e.failed===undefined||(Array.isArray(e.failed)&&new Set(e.failed).size===e.failed.length&&e.failed.every(n=>Number.isInteger(n)&&bySubject(e.subject).some(t=>Number(t.code)===n)));
window.examFlow={open,checkpoint,dates,apply};window.renderRoadmap?.();
})();
